class Review:
    def __init__(self, checklist):
        self.checklist = checklist
        self.findings = []

    def check(self, item, passed, note=""):
        self.findings.append((item, passed, note))

    def summary(self):
        failed = [f for f in self.findings if not f[1]]
        return failed


checklist = ["legibilidad", "corrección", "tests", "consistencia"]
review = Review(checklist)
review.check("legibilidad", True)
review.check("corrección", True)
review.check("tests", False, "falta manejo de error en getUser")
review.check("consistencia", True)

for item, passed, note in review.findings:
    estado = "OK" if passed else "FALTA"
    linea = f"{item}: {estado}"
    if note:
        linea += f" -- {note}"
    print(linea)

pending = review.summary()
if pending:
    print(f"revisión bloqueada: {len(pending)} punto(s) pendiente(s)")
else:
    print("revisión aprobada")
